 "content": "def transform(grid):
    """Copy the colored marker's shape onto every all-zero translated match."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 1)}
    if len(colors) != 1:
        return [row[:] for row in grid]
    color = next(iter(colors))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]
    sh, sw = max_r - min_r + 1, max_c - min_c + 1
    out = [row[:] for row in grid]
    for r0 in range(h - sh + 1):
        for c0 in range(w - sw + 1):
            if all(grid[r0 + dr][c0 + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r0 + dr][c0 + dc] = color
    return out
